"use client"

import * as React from "react"

import { cn } from "@/lib/utils"
import { ChangeList, defaultFormatValue, type Change, type FormatValue } from "@/registry/tellerline/change-list/change-list"
import {
  canDecide,
  canWithdraw,
  evaluateApproval,
  type ApprovalPolicy,
  type ApprovalRequest,
  type ApprovalStatus,
  type DecideBlock,
  type Person,
} from "@/registry/tellerline/lib/approval"
import { formatRelative } from "@/registry/tellerline/lib/time"

export type MakerCheckerRequest = ApprovalRequest & {
  title: React.ReactNode
  /** One line under the title, such as the amount and beneficiary. */
  summary?: React.ReactNode
  /** What the request would change, shown as before and after. */
  changes?: Change[]
}

export type MakerCheckerProps = Omit<React.ComponentProps<"section">, "children" | "title"> & {
  request: MakerCheckerRequest
  policy: ApprovalPolicy
  /** The person looking at the request. Decides which actions they get, and the reason when they get none. */
  viewer: Person
  /** Called with the comment, which may be empty. Return a promise to show a pending state; throw to show an error. */
  onApprove?: (comment: string) => void | Promise<void>
  /** Called with the reason, which is required. */
  onReject?: (reason: string) => void | Promise<void>
  onWithdraw?: () => void | Promise<void>
  formatValue?: FormatValue
  locale?: string
  timeZone?: string
  /** Pass it to show relative times. Left out, only absolute times are shown, so server and client render the same. */
  now?: Date
  headingLevel?: 2 | 3 | 4 | 5 | 6
}

const STATUS: Record<ApprovalStatus, { label: string; dot: string }> = {
  pending: { label: "Pending approval", dot: "bg-amber-500 dark:bg-amber-400" },
  approved: { label: "Approved", dot: "bg-emerald-600 dark:bg-emerald-400" },
  rejected: { label: "Rejected", dot: "bg-destructive" },
  withdrawn: { label: "Withdrawn", dot: "bg-muted-foreground" },
}

const button = {
  base: "inline-flex h-9 items-center justify-center gap-2 rounded-md px-4 text-sm font-medium whitespace-nowrap transition-[color,background-color,box-shadow] outline-none focus-visible:ring-[3px] focus-visible:ring-ring/50 disabled:pointer-events-none disabled:opacity-50",
  primary: "bg-primary text-primary-foreground shadow-xs hover:bg-primary/90",
  outline: "border-input bg-background hover:bg-accent hover:text-accent-foreground border shadow-xs",
}

const join = (names: string[], locale: string) => new Intl.ListFormat(locale, { type: "conjunction" }).format(names)

/**
 * A change that needs a second pair of eyes. It shows what would change, who has approved so far and how many
 * approvals are still needed. Each viewer gets only the actions the policy allows, and a plain reason when they get none.
 */
export function MakerChecker({
  request,
  policy,
  viewer,
  onApprove,
  onReject,
  onWithdraw,
  formatValue = defaultFormatValue,
  locale = "en-US",
  timeZone,
  now,
  headingLevel = 3,
  className,
  ...props
}: MakerCheckerProps) {
  const Heading = `h${headingLevel}` as const
  const state = evaluateApproval(request, policy)
  const decide = canDecide(request, policy, viewer)
  const withdraw = canWithdraw(request, policy, viewer)

  const dateTime = new Intl.DateTimeFormat(locale, { timeZone, dateStyle: "medium", timeStyle: "short" })
  const full = new Intl.DateTimeFormat(locale, { timeZone, dateStyle: "full", timeStyle: "long" })
  const when = (at: Date | string) => {
    const date = new Date(at)
    return (
      <time dateTime={date.toISOString()} title={full.format(date)}>
        {now ? formatRelative(date, now, locale) : dateTime.format(date)}
      </time>
    )
  }

  const id = React.useId()
  const commentRef = React.useRef<HTMLTextAreaElement>(null)
  const [comment, setComment] = React.useState("")
  const [needsReason, setNeedsReason] = React.useState(false)
  const [busy, setBusy] = React.useState<"approve" | "reject" | "withdraw" | null>(null)
  const [error, setError] = React.useState<string | null>(null)
  const [announcement, setAnnouncement] = React.useState("")

  const run = async (action: "approve" | "reject" | "withdraw", fn: () => void | Promise<void>, done: string) => {
    setBusy(action)
    setError(null)
    try {
      await fn()
      setComment("")
      setNeedsReason(false)
      setAnnouncement(done)
    } catch (e) {
      setError(e instanceof Error && e.message ? e.message : "That didn't go through. Try again.")
    } finally {
      setBusy(null)
    }
  }

  const reject = () => {
    if (!comment.trim()) {
      setNeedsReason(true)
      commentRef.current?.focus()
      return
    }
    void run("reject", () => onReject?.(comment.trim()), "Your rejection was recorded.")
  }

  const status = STATUS[state.status]
  const approvers = state.approvals.map((d) => d.by.name)

  return (
    <section
      data-slot="maker-checker"
      aria-labelledby={`${id}-title`}
      className={cn("bg-card text-card-foreground overflow-hidden rounded-xl border text-sm shadow-xs", className)}
      {...props}
    >
      <div className="grid gap-5 p-5 sm:p-6">
        <header className="flex flex-wrap items-start justify-between gap-x-6 gap-y-3">
          <div className="grid min-w-0 gap-1">
            <Heading id={`${id}-title`} className="text-base font-semibold tracking-tight">
              {request.title}
            </Heading>
            {request.summary && <p className="text-muted-foreground">{request.summary}</p>}
            <p className="text-muted-foreground text-xs">
              Requested by <span className="text-foreground">{request.maker.name}</span> · {when(request.createdAt)}
            </p>
          </div>
          <span className="bg-muted inline-flex shrink-0 items-center gap-2 rounded-full px-2.5 py-1 text-xs font-medium">
            <span aria-hidden className={cn("size-1.5 rounded-full", status.dot)} />
            {status.label}
          </span>
        </header>

        <div className="grid gap-2">
          <p className="text-xs">
            <span className="font-medium">
              {state.approvals.length} of {state.required}
            </span>{" "}
            <span className="text-muted-foreground">{state.required === 1 ? "approval" : "approvals"}</span>
          </p>
          <div aria-hidden className="flex gap-1">
            {Array.from({ length: state.required }, (_, i) => (
              <span
                key={i}
                className={cn(
                  "h-1 flex-1 rounded-full",
                  i < state.approvals.length ? "bg-emerald-600 dark:bg-emerald-400" : state.status === "rejected" ? "bg-destructive/30" : "bg-foreground/10",
                )}
              />
            ))}
          </div>
        </div>

        {request.changes && request.changes.length > 0 && <ChangeList changes={request.changes} formatValue={formatValue} />}

        {request.decisions.length > 0 && (
          <ol className="grid gap-3" aria-label="Decisions">
            {[...request.decisions]
              .sort((a, b) => new Date(a.at).getTime() - new Date(b.at).getTime())
              .map((d, i) => {
                const ignored = state.ignored.find((x) => x.decision === d)
                return (
                  <li key={`${d.by.id}-${i}`} className="grid gap-1">
                    <p>
                      <span className="font-medium">{d.by.name}</span>{" "}
                      <span className={d.decision === "approve" ? "text-foreground" : "text-destructive"}>
                        {d.decision === "approve" ? "approved" : "rejected"}
                      </span>{" "}
                      <span className="text-muted-foreground text-xs">
                        · {when(d.at)}
                      </span>
                      {ignored && <span className="text-muted-foreground text-xs"> · not counted</span>}
                    </p>
                    {d.comment && <p className="text-muted-foreground border-s-2 ps-3">{d.comment}</p>}
                  </li>
                )
              })}
          </ol>
        )}
      </div>

      <div aria-busy={busy !== null} className="bg-muted/40 grid gap-4 border-t p-5 sm:px-6">
        {decide.ok && (
          <>
            <div className="grid gap-2">
              <label htmlFor={`${id}-comment`} className="text-sm font-medium">
                Comment <span className="text-muted-foreground font-normal">· required to reject</span>
              </label>
              <textarea
                ref={commentRef}
                id={`${id}-comment`}
                value={comment}
                rows={2}
                onChange={(e) => {
                  setComment(e.target.value)
                  if (e.target.value.trim()) setNeedsReason(false)
                }}
                aria-invalid={needsReason || undefined}
                aria-describedby={needsReason ? `${id}-reason` : undefined}
                className="border-input bg-background placeholder:text-muted-foreground focus-visible:border-ring focus-visible:ring-ring/50 aria-invalid:border-destructive aria-invalid:ring-destructive/20 min-h-16 w-full rounded-md border px-3 py-2 text-sm shadow-xs outline-none focus-visible:ring-[3px]"
              />
              {needsReason && (
                <p id={`${id}-reason`} className="text-destructive text-xs">
                  Add a reason, so {request.maker.name} knows what to fix.
                </p>
              )}
            </div>
            <div className="flex flex-wrap gap-2">
              <button
                type="button"
                disabled={busy !== null}
                onClick={() => void run("approve", () => onApprove?.(comment.trim()), "Your approval was recorded.")}
                className={cn(button.base, button.primary)}
              >
                {busy === "approve" ? "Approving…" : "Approve"}
              </button>
              <button type="button" disabled={busy !== null} onClick={reject} className={cn(button.base, button.outline, "text-destructive")}>
                {busy === "reject" ? "Rejecting…" : "Reject"}
              </button>
            </div>
          </>
        )}

        {!decide.ok && (
          <div className="flex flex-wrap items-center justify-between gap-x-6 gap-y-3">
            <p className="text-muted-foreground">{explain(decide.reason, state, request, policy, viewer, locale, approvers)}</p>
            {withdraw.ok && (
              <button
                type="button"
                disabled={busy !== null}
                onClick={() => void run("withdraw", () => onWithdraw?.(), "The request was withdrawn.")}
                className={cn(button.base, button.outline)}
              >
                {busy === "withdraw" ? "Withdrawing…" : "Withdraw request"}
              </button>
            )}
          </div>
        )}

        {error && (
          <p role="alert" className="text-destructive text-sm">
            {error}
          </p>
        )}
        <p role="status" className="sr-only">
          {announcement}
        </p>
      </div>
    </section>
  )
}

function explain(
  reason: DecideBlock,
  state: ReturnType<typeof evaluateApproval>,
  request: MakerCheckerRequest,
  policy: ApprovalPolicy,
  viewer: Person,
  locale: string,
  approvers: string[],
): string {
  const waiting = `${state.remaining} more ${state.remaining === 1 ? "approval" : "approvals"} needed`
  switch (reason) {
    case "own-request":
      return `You created this request, so someone else has to approve it. ${waiting}.`
    case "missing-role":
      return `Only people with the ${join(policy.approverRoles ?? [], locale)} role can approve this request. ${waiting}.`
    case "already-decided":
      return `You've already approved this. ${waiting} from other people.`
    case "not-pending":
      if (state.status === "approved") return `Approved by ${join(approvers, locale)}.`
      if (state.status === "rejected")
        return `Rejected by ${state.rejection?.by.id === viewer.id ? "you" : state.rejection?.by.name}${state.rejection?.comment ? `: “${state.rejection.comment}”` : "."}`
      return `${request.maker.id === viewer.id ? "You" : request.maker.name} withdrew this request.`
  }
}

import * as React from "react"

/** One field that changed. Leave out `from` for a value that was added, or `to` for one that was removed. */
export type Change = {
  /** Machine name of the field, passed to `formatValue`. */
  field: string
  /** What people see. Defaults to `field`. */
  label?: string
  from?: unknown
  to?: unknown
}

export type FormatValue = (field: string, value: unknown) => React.ReactNode

export const defaultFormatValue: FormatValue = (_field, value) => {
  if (value === null || value === undefined || value === "") return <span className="text-muted-foreground italic">empty</span>
  if (typeof value === "boolean") return value ? "Yes" : "No"
  if (value instanceof Date) return value.toISOString()
  return String(value)
}

/**
 * Field-level before and after values as a description list. The old value is a <del> and the new one an <ins>,
 * with visually hidden "from" and "to" so screen readers don't depend on the arrow.
 */
export function ChangeList({ changes, formatValue = defaultFormatValue }: { changes: Change[]; formatValue?: FormatValue }) {
  return (
    // A container query, so the label sits beside the values only where the list itself has room.
    <div className="@container">
      <dl className="bg-muted/50 grid grid-cols-1 gap-x-4 rounded-md px-3 py-2 text-xs @sm:grid-cols-[minmax(6rem,auto)_1fr] @sm:gap-y-1.5">
        {changes.map((change) => (
          <React.Fragment key={change.field}>
            <dt className="text-muted-foreground mt-2 first:mt-0 @sm:mt-0">{change.label ?? change.field}</dt>
            <dd className="flex min-w-0 flex-wrap items-baseline gap-x-2 tabular-nums">
              {"from" in change && (
                <del className="text-muted-foreground decoration-destructive/60">
                  <span className="sr-only">from </span>
                  {formatValue(change.field, change.from)}
                </del>
              )}
              {"from" in change && "to" in change && (
                <span aria-hidden className="text-muted-foreground">
                  →
                </span>
              )}
              {"to" in change && (
                <ins className="text-foreground no-underline">
                  <span className="sr-only">to </span>
                  {formatValue(change.field, change.to)}
                </ins>
              )}
            </dd>
          </React.Fragment>
        ))}
      </dl>
    </div>
  )
}

/**
 * Maker-checker rules, as plain functions. The same functions belong on the server: run them before saving a
 * decision, because a hidden button is a hint, not a control.
 *
 * The rules:
 * - The maker never approves their own request, whatever their roles.
 * - Each person counts once, however many times they approve.
 * - If approverRoles is set, only people with one of those roles count.
 * - One rejection ends the request.
 * - The maker can withdraw while the request is pending.
 * - Nothing that happens after the request is approved, rejected or withdrawn changes the outcome.
 */

export type Person = { id: string; name: string; roles?: string[] }

export type Decision = {
  by: Person
  decision: "approve" | "reject"
  at: Date | string
  comment?: string
}

export type ApprovalRequest = {
  id: string
  maker: Person
  createdAt: Date | string
  decisions: Decision[]
  /** Set when the maker withdrew the request. */
  withdrawnAt?: Date | string
}

export type ApprovalPolicy = {
  /** How many distinct approvals the request needs. At least 1. */
  requiredApprovals: number
  /** When set, only people with at least one of these roles can approve or reject. */
  approverRoles?: string[]
}

export type ApprovalStatus = "pending" | "approved" | "rejected" | "withdrawn"

export type IgnoredReason = "own-request" | "missing-role" | "duplicate" | "after-final"

export type ApprovalState = {
  status: ApprovalStatus
  required: number
  /** The approvals that count, in the order they were made. */
  approvals: Decision[]
  remaining: number
  /** The rejection that ended the request, if any. */
  rejection?: Decision
  /** Decisions that were made but don't count, with the reason. */
  ignored: { decision: Decision; reason: IgnoredReason }[]
  /** When the request reached its final state. */
  decidedAt?: Date
}

export type Permission<R extends string> = { ok: true } | { ok: false; reason: R }

export type DecideBlock = "not-pending" | "own-request" | "missing-role" | "already-decided"
export type WithdrawBlock = "not-pending" | "not-maker"

const time = (value: Date | string) => new Date(value).getTime()

function eligible(person: Person, policy: ApprovalPolicy) {
  if (!policy.approverRoles?.length) return true
  return (person.roles ?? []).some((role) => policy.approverRoles!.includes(role))
}

/** Works out where a request stands under a policy. */
export function evaluateApproval(request: ApprovalRequest, policy: ApprovalPolicy): ApprovalState {
  const required = Math.max(1, Math.floor(policy.requiredApprovals))
  const withdrawnAt = request.withdrawnAt === undefined ? undefined : time(request.withdrawnAt)
  const decisions = [...request.decisions].sort((a, b) => time(a.at) - time(b.at))

  const approvals: Decision[] = []
  const ignored: ApprovalState["ignored"] = []
  const seen = new Set<string>()
  let status: ApprovalStatus = "pending"
  let rejection: Decision | undefined
  let decidedAt: Date | undefined

  for (const decision of decisions) {
    const at = time(decision.at)
    if (status === "pending" && withdrawnAt !== undefined && at >= withdrawnAt) {
      status = "withdrawn"
      decidedAt = new Date(withdrawnAt)
    }
    if (status !== "pending") {
      ignored.push({ decision, reason: "after-final" })
      continue
    }
    if (decision.by.id === request.maker.id) {
      ignored.push({ decision, reason: "own-request" })
      continue
    }
    if (!eligible(decision.by, policy)) {
      ignored.push({ decision, reason: "missing-role" })
      continue
    }
    if (seen.has(decision.by.id)) {
      ignored.push({ decision, reason: "duplicate" })
      continue
    }
    seen.add(decision.by.id)
    if (decision.decision === "reject") {
      status = "rejected"
      rejection = decision
      decidedAt = new Date(at)
    } else {
      approvals.push(decision)
      if (approvals.length >= required) {
        status = "approved"
        decidedAt = new Date(at)
      }
    }
  }

  if (status === "pending" && withdrawnAt !== undefined) {
    status = "withdrawn"
    decidedAt = new Date(withdrawnAt)
  }

  return { status, required, approvals, remaining: Math.max(0, required - approvals.length), rejection, ignored, decidedAt }
}

/** Whether a person may approve or reject the request now, and if not, why. */
export function canDecide(request: ApprovalRequest, policy: ApprovalPolicy, viewer: Person): Permission<DecideBlock> {
  const state = evaluateApproval(request, policy)
  if (state.status !== "pending") return { ok: false, reason: "not-pending" }
  if (viewer.id === request.maker.id) return { ok: false, reason: "own-request" }
  if (!eligible(viewer, policy)) return { ok: false, reason: "missing-role" }
  if (request.decisions.some((d) => d.by.id === viewer.id)) return { ok: false, reason: "already-decided" }
  return { ok: true }
}

/** Whether a person may withdraw the request now, and if not, why. */
export function canWithdraw(request: ApprovalRequest, policy: ApprovalPolicy, viewer: Person): Permission<WithdrawBlock> {
  if (evaluateApproval(request, policy).status !== "pending") return { ok: false, reason: "not-pending" }
  if (viewer.id !== request.maker.id) return { ok: false, reason: "not-maker" }
  return { ok: true }
}

export type ApprovalTier = {
  /** Lowest amount this tier applies to, as a decimal string. */
  from: string
  approvals: number
}

/**
 * The number of approvals an amount needs, from tiers like [{ from: "0", approvals: 1 }, { from: "10000", approvals: 2 }].
 * Amounts are compared as exact minor units, so "9999.995" never rounds into the next tier.
 */
export function requiredApprovalsFor(amount: string, tiers: ApprovalTier[]): number {
  const scale = Math.max(fractionLength(amount), ...tiers.map((t) => fractionLength(t.from)))
  const value = scaled(absolute(amount), scale)
  let result = 1
  let best: bigint | undefined
  for (const tier of tiers) {
    const from = scaled(tier.from, scale)
    if (value >= from && (best === undefined || from >= best)) {
      best = from
      result = tier.approvals
    }
  }
  return result
}

const absolute = (value: string) => value.trim().replace(/^-/, "")
const fractionLength = (value: string) => value.split(".")[1]?.length ?? 0

function scaled(value: string, scale: number): bigint {
  if (!/^-?\d+(\.\d+)?$/.test(value.trim())) throw new Error(`Not a decimal string: ${value}`)
  const [int, frac = ""] = value.trim().split(".")
  return BigInt(int + frac.padEnd(scale, "0"))
}

const UNITS: [Intl.RelativeTimeFormatUnit, number][] = [
  ["year", 31536000],
  ["month", 2592000],
  ["week", 604800],
  ["day", 86400],
  ["hour", 3600],
  ["minute", 60],
  ["second", 1],
]

/** "2 hours ago", "yesterday", "in 3 days", in the given locale. */
export function formatRelative(date: Date, now: Date, locale = "en-US"): string {
  const seconds = Math.round((date.getTime() - now.getTime()) / 1000)
  const rtf = new Intl.RelativeTimeFormat(locale, { numeric: "auto" })
  for (const [unit, size] of UNITS) if (Math.abs(seconds) >= size || unit === "second") return rtf.format(Math.round(seconds / size), unit)
  return ""
}
